1	import type { Item } from "./insured-item.js";
2	import { amountOwedByMhpco } from "./mhpcos-favor.js";
3	import { insuranceValue } from "./price-list.js";
4	
5	export interface Damage {
6	  itemType: string;
7	  amount: number;
8	}
9	
10	export interface Incident {
11	  cause: string;
12	  damages: Damage[];
13	}
14	
15	export interface Policy {
16	  insuredItems: Item[];
17	  // How much the MHPCO may still pay out over this policy's lifetime. This is
18	  // the single figure the MHPCO tracks per policy: opening the policy sets it
19	  // to the full cap, and each claim depletes it. The insurance sum it is
20	  // derived from is never reported on its own.
21	  remainingCap: number;
22	}
23	
24	export interface ClaimResult {
25	  payout: number;
26	  remainingCap: number;
27	  // The policy as it stands after this claim, for settling the next one.
28	  policy: Policy;
29	}
30	
31	const DEDUCTIBLE_PER_DAMAGE = 100;
32	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
33	
34	// The MHPCO insures a policy for the sum of its items' insurance values.
35	function insuranceSum(insuredItems: Item[]): number {
36	  return insuredItems
37	    .map(insuranceValue)
38	    .reduce((sum, value) => sum + value, 0);
39	}
40	
41	// The MHPCO pays out at most twice the insurance sum over a policy's lifetime.
42	// A policy is opened with that whole cap intact; each claim depletes it.
43	export function openPolicy(insuredItems: Item[]): Policy {
44	  return {
45	    insuredItems,
46	    remainingCap: insuranceSum(insuredItems) * CAP_MULTIPLE_OF_INSURANCE_SUM,
47	  };
48	}
49	
50	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
51	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
52	const FULL_REIMBURSEMENT_RATE = 1;
53	
54	// A damage entry names only the type of the item it befell, so the MHPCO
55	// identifies the covering item no further than the policy's first insured item
56	// of that type. Where a policy covers several alike items this is a deliberate
57	// approximation: alike items share the traits the reimbursement clauses read,
58	// so any of them yields the same clause.
59	function firstInsuredItemCoveringDamage(
60	  policy: Policy,
61	  damage: Damage,
62	): Item | undefined {
63	  return policy.insuredItems.find((item) => item.type === damage.itemType);
64	}
65	
66	// The conditions on which the MHPCO accepts a damage entry at all, checked
67	// before it settles anything: it settles a damage only against an item the
68	// policy actually covers, and a damage event reports what was lost, so its
69	// amount cannot be negative. An entry that fails either condition is refused,
70	// and the whole claim with it. Counting damage entries against the insured
71	// items of their type -- and refusing an excess -- is a further condition the
72	// MHPCO has not yet put into force; it belongs here when it does. Accepting an
73	// entry yields the covering item, since establishing coverage is what finds it.
74	function acceptedDamageEntryCover(policy: Policy, damage: Damage): Item {
75	  const covering = firstInsuredItemCoveringDamage(policy, damage);
76	  if (covering === undefined) {
77	    throw new Error(`the policy does not cover "${damage.itemType}"`);
78	  }
79	  if (damage.amount < 0) {
80	    throw new Error(
81	      `a damage amount cannot be negative, but "${damage.itemType}" reports ${damage.amount}`,
82	    );
83	  }
84	  return covering;
85	}
86	
87	function isHighlyEnchanted(item: Item): boolean {
88	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
89	}
90	
91	// Which reimbursement clause covers the damaged item. Damage to a highly
92	// enchanted item is reimbursed at half; all other damage in full.
93	// The dragon-material clause is subsumed by that default: it reimburses in
94	// full, and where it meets the high-enchantment clause the 50 % rate wins, so
95	// it never changes a payout and needs no branch of its own.
96	// Every item reaching a clause is one the policy covers: whether the MHPCO
97	// accepts the damage entry at all is settled beforehand, not here.
98	function reimbursementRateFor(item: Item): number {
99	  return isHighlyEnchanted(item)
100	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
101	    : FULL_REIMBURSEMENT_RATE;
102	}
103	
104	// The MHPCO settles each accepted damage event separately: it reimburses the
105	// damage under the applicable clause, then withholds its deductible once per
106	// event.
107	function settlementForDamageEvent(policy: Policy, damage: Damage): number {
108	  const rate = reimbursementRateFor(acceptedDamageEntryCover(policy, damage));
109	  return damage.amount * rate - DEDUCTIBLE_PER_DAMAGE;
110	}
111	
112	// What the MHPCO owes for the whole incident before rounding: every damage
113	// event settled under its clause, reduced to what the policy's lifetime cap
114	// still allows.
115	function countByType(types: string[]): Map<string, number> {
116	  const counts = new Map<string, number>();
117	  for (const type of types) {
118	    counts.set(type, (counts.get(type) ?? 0) + 1);
119	  }
120	  return counts;
121	}
122	
123	// An incident can damage an insured item only once, so the MHPCO refuses an
124	// incident reporting more damages of a type than the policy covers of it.
125	function refuseMoreDamagesThanInsured(policy: Policy, incident: Incident): void {
126	  const insured = countByType(policy.insuredItems.map((item) => item.type));
127	  for (const [type, damaged] of countByType(
128	    incident.damages.map((damage) => damage.itemType),
129	  )) {
130	    if (damaged > (insured.get(type) ?? 0)) {
131	      throw new Error(
132	        `the policy covers ${insured.get(type) ?? 0} of "${type}", but the incident reports ${damaged} damaged`,
133	      );
134	    }
135	  }
136	}
137	
138	function cappedSettlement(policy: Policy, incident: Incident): number {
139	  refuseMoreDamagesThanInsured(policy, incident);
140	  const settled = incident.damages
141	    .map((damage) => settlementForDamageEvent(policy, damage))
142	    .reduce((sum, amount) => sum + amount, 0);
143	  return Math.min(settled, policy.remainingCap);
144	}
145	
146	export function claim(policy: Policy, incident: Incident): ClaimResult {
147	  // A payout is owed by the MHPCO, so its fraction is rounded down. Only this
148	  // final amount is rounded; the settlement above stays fractional. Rounding
149	  // last is safe for a capped claim too: the cap is always a whole number of
150	  // G, so rounding a capped settlement changes nothing.
151	  const payout = amountOwedByMhpco(cappedSettlement(policy, incident));
152	  const remainingCap = policy.remainingCap - payout;
153	  return { payout, remainingCap, policy: { ...policy, remainingCap } };
154	}
